using RedKey.Domain.Common;
using RedKey.Domain.Entities.Identity;
using RedKey.Domain.Enums;
using RedKey.Domain.ValueObjects;

namespace RedKey.Domain.Entities.Units;

public class PropertyUnit : BaseEntity
{
    private readonly List<UnitImage> _images = [];
    private readonly List<UnitPaymentPlan> _paymentPlans = [];
    private readonly List<UnitFeature> _features = [];

    private PropertyUnit() { }

    /// <summary>RK-xxxx, generated by the database sequence.</summary>
    public string Code { get; private set; } = null!; // null → the database default (sequence) fills it

    public int UnitTypeId { get; private set; }
    /// <summary>Copied from the area so listings show the city without going through the area.</summary>
    public int CityId { get; private set; }
    public int AreaId { get; private set; }
    public UnitPurpose Purpose { get; private set; }
    public string TitleAr { get; private set; } = string.Empty;
    public string TitleEn { get; private set; } = string.Empty;
    public string CompoundAr { get; private set; } = string.Empty;
    public string CompoundEn { get; private set; } = string.Empty;
    public decimal Price { get; private set; }
    public int Bedrooms { get; private set; }
    public int Bathrooms { get; private set; }
    public decimal Size { get; private set; }
    public FinishingType Finishing { get; private set; }
    public string CoverImageUrl { get; private set; } = string.Empty;
    public bool IsFeatured { get; private set; }
    public decimal BrokerCommission { get; private set; }
    /// <summary>Paid by the customer when the viewing takes place (0 = free). Set by the super admin only.</summary>
    public decimal ViewingFee { get; private set; }

    public UnitStatus Status { get; private set; }
    public string? ReviewNote { get; private set; }
    public Guid CreatedByUserId { get; private set; }
    public UserRole CreatedByRole { get; private set; }
    public Guid? ReviewedByUserId { get; private set; }
    public DateTime? ReviewedAtUtc { get; private set; }
    public bool IsDeleted { get; private set; }

    public UnitType UnitType { get; private set; } = null!;
    public City City { get; private set; } = null!;
    public Area Area { get; private set; } = null!;
    public ApplicationUser CreatedBy { get; private set; } = null!;
    public UnitDetails Details { get; private set; } = null!;
    public IReadOnlyCollection<UnitImage> Images => _images;
    public IReadOnlyCollection<UnitPaymentPlan> PaymentPlans => _paymentPlans;
    public IReadOnlyCollection<UnitFeature> Features => _features;

    /// <summary>A super admin unit is published right away; a broker unit waits for review.</summary>
    public static PropertyUnit Create(UnitContent content, Guid createdByUserId, UserRole createdByRole)
    {
        var unit = new PropertyUnit
        {
            CreatedByUserId = createdByUserId,
            CreatedByRole = createdByRole,
            Status = createdByRole == UserRole.SuperAdmin ? UnitStatus.Approved : UnitStatus.PendingReview,
            Details = new UnitDetails()
        };
        unit.SetContent(content);
        return unit;
    }

    public void SetContent(UnitContent c)
    {
        UnitTypeId = c.UnitTypeId;
        CityId = c.CityId;
        AreaId = c.AreaId;
        Purpose = c.Purpose;
        TitleAr = c.TitleAr;
        TitleEn = c.TitleEn;
        CompoundAr = c.CompoundAr;
        CompoundEn = c.CompoundEn;
        Price = c.Price;
        Bedrooms = c.Bedrooms;
        Bathrooms = c.Bathrooms;
        Size = c.Size;
        Finishing = c.Finishing;
        IsFeatured = c.IsFeatured;
        BrokerCommission = c.BrokerCommission;
        Details.Set(c.DescriptionAr, c.DescriptionEn, c.DeliveryAr, c.DeliveryEn);
    }

    public void SetViewingFee(decimal fee) => ViewingFee = fee;

    public void SetCoverImage(string url) => CoverImageUrl = url;

    /// <summary>Replaces the detail-page gallery (in order).</summary>
    public void SetGallery(IEnumerable<string> urls)
    {
        _images.Clear();
        var order = 0;
        foreach (var url in urls)
            _images.Add(UnitImage.Create(url, ++order));
    }

    public void SetPaymentPlans(IEnumerable<PaymentPlanContent> plans)
    {
        _paymentPlans.Clear();
        var order = 0;
        foreach (var p in plans)
            _paymentPlans.Add(UnitPaymentPlan.Create(p, ++order));
    }

    public void SetFeatures(IEnumerable<LocalizedPair> features)
    {
        _features.Clear();
        var order = 0;
        foreach (var f in features)
            _features.Add(UnitFeature.Create(f, ++order));
    }

    /// <summary>Any broker edit sends the unit back to the review queue.</summary>
    public void SubmitForReview()
    {
        Status = UnitStatus.PendingReview;
        ReviewedByUserId = null;
        ReviewedAtUtc = null;
    }

    public void Review(UnitReviewDecision decision, string? note, Guid reviewerId, DateTime nowUtc)
    {
        Status = decision switch
        {
            UnitReviewDecision.Approve => UnitStatus.Approved,
            UnitReviewDecision.RequestChanges => UnitStatus.ChangesRequested,
            UnitReviewDecision.Reject => UnitStatus.Rejected,
            _ => throw new ArgumentOutOfRangeException(nameof(decision), decision, null)
        };
        ReviewNote = string.IsNullOrWhiteSpace(note) ? null : note.Trim();
        ReviewedByUserId = reviewerId;
        ReviewedAtUtc = nowUtc;
    }

    public void Delete() => IsDeleted = true;
}
